    Rec* start; Rec* finish; Rec* eos; int overflowCalls; unsigned int overflowN;
    void insert_overflow(Rec*, const Rec&, unsigned int n) { ++overflowCalls; overflowN = n; }
    void fill_insert(Rec* pos, unsigned int n, const Rec& x)
